//go:build libopus && cgo

package opus

import (
	"encoding/hex"
	"errors"
	"testing"
)

// A 20ms libopus packet generated by FFmpeg/libopus from a 440Hz 16kHz
// sinusoid. This is a raw codec packet, not an Ogg container.
const rawOpusFixture = "48825b036c9e99ac000002c59ec5f7833ccef00061ff484409fd0e07d13cf69a2b8f3d2539f430d1bb7d5e5f28f791ec28e45742a9597cc773ea35d64cf9f7a0a8"

func TestNativeRawPacketDecode(t *testing.T) {
	packet, err := hex.DecodeString(rawOpusFixture)
	if err != nil {
		t.Fatal(err)
	}
	for _, rate := range []int{8000, 16000, 48000} {
		d, err := NewDecoder(rate, 1)
		if err != nil {
			t.Fatal(err)
		}
		out, err := d.Decode(packet)
		if err != nil {
			t.Fatalf("rate %d: %v", rate, err)
		}
		if len(out) < rate*2/100 || len(out) > rate*2*120/1000 {
			t.Fatalf("rate %d: invalid decoded size %d", rate, len(out))
		}
		if d.OutputFormat().SampleRate != rate {
			t.Fatal("wrong output rate")
		}
		if _, err := d.Decode(nil); !errors.Is(err, ErrInvalidPacket) {
			t.Fatal(err)
		}
		if err := d.Close(); err != nil {
			t.Fatal(err)
		}
		if err := d.Close(); err != nil {
			t.Fatal(err)
		}
		if _, err := d.Decode(packet); !errors.Is(err, ErrClosed) {
			t.Fatal(err)
		}
	}
}
